export const PRACTICE_MESSAGES = Object.freeze(Object.fromEntries(['de','en','uk','ar','tr'].map((locale,index) => [locale,Object.freeze(Object.fromEntries(Object.entries(rows).map(([key,values]) => [key,values[index]])))])));
registerMessages('practice', PRACTICE_MESSAGES);
export const pt = (key, parameters = {}, locale = getLocale()) => t('practice.' + key, parameters, locale);
const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
function safeParameters(value) {
  try {
    if (!value || typeof value !== 'object' || ![Object.prototype,null].includes(Object.getPrototypeOf(value))) return null;
    const out=Object.create(null);
    for (const key of Reflect.ownKeys(value)) {
      const descriptor=Object.getOwnPropertyDescriptor(value,key);
      if (typeof key !== 'string' || !/^[A-Za-z][A-Za-z0-9_]*$/.test(key) || !descriptor || !Object.hasOwn(descriptor,'value')) return null;
      const item=descriptor.value;
      if (!(typeof item === 'string' || typeof item === 'boolean' || typeof item === 'bigint' || typeof item === 'number' && Number.isFinite(item))) return null;
      out[key]=typeof item === 'bigint' ? String(item) : item;
    }
    return out;
  } catch { return null; }
}
export function pl(key, parameters = {}, locale = getLocale()) {
  const safe=safeParameters(parameters); if (!safe) key='';
  return '<span data-practice-key="'+escape(key)+'" data-practice-params="'+escape(JSON.stringify(safe || {}))+'">'+escape(pt(key,safe || {},locale))+'</span>';
}
export function bindPracticeText(node, key, parameters = {}, locale = getLocale()) {
  if (!node) return;
  const safe=safeParameters(parameters); if (!safe) key='';
  node.dataset.practiceKey=key; node.dataset.practiceParams=JSON.stringify(safe || {});
  node.textContent=pt(key,safe || {},locale);
}
export function updatePracticeLocale(root, locale = getLocale()) {
  if (!root) return;
  for (const node of root.querySelectorAll('[data-practice-date]')) if (node.isConnected && !node.children?.length) node.textContent=formatDate(node.dataset.practiceDate,{dateStyle:'medium',timeStyle:'short'},locale);
  const nodes = [...(root.matches?.('[data-practice-key]') ? [root] : []), ...root.querySelectorAll('[data-practice-key]')];
  for (const node of nodes) {
    if (!node.isConnected || node.children?.length || ['INPUT','TEXTAREA','SELECT','SCRIPT','STYLE'].includes(node.tagName)) continue;
    let parameters; try { parameters = JSON.parse(node.dataset.practiceParams || '{}'); } catch { continue; }
    node.textContent = pt(node.dataset.practiceKey,parameters,locale);
  }
  for (const attribute of ['aria-label','title','placeholder']) for (const node of root.querySelectorAll('[data-practice-' + attribute + ']')) {
    if (!node.isConnected) continue;
    let parameters; try { parameters = JSON.parse(node.dataset.practiceParams || '{}'); } catch { continue; }
    node.setAttribute(attribute,pt(node.getAttribute('data-practice-' + attribute),parameters,locale));
  }
}

export function pa(attribute, key, parameters = {}, locale = getLocale()) {
  if (!['aria-label','title','placeholder'].includes(attribute)) return '';
  const safe=safeParameters(parameters); if (!safe) key='';
  return `${attribute}="${escape(pt(key,safe || {},locale))}" data-practice-${attribute}="${escape(key)}" data-practice-params="${escape(JSON.stringify(safe || {}))}"`;
}
